import{_ as t}from"./plugin-vue_export-helper-c27b6911.js";import{o as e,c as l,e as i}from"./app-db7b9325.js";const a={},d=i('<h1 id="dalvik-虚拟机与-smali-基础" tabindex="-1"><a class="header-anchor" href="#dalvik-虚拟机与-smali-基础" aria-hidden="true">#</a> Dalvik 虚拟机与 Smali 基础</h1><p>Dalvik 是 Android 早期版本中使用的进程虚拟机，用于执行 Android 应用。了解它及其汇编语言 Smali 是逆向分析的基石。</p><h2 id="_1-dalvik-vs-jvm" tabindex="-1"><a class="header-anchor" href="#_1-dalvik-vs-jvm" aria-hidden="true">#</a> 1. Dalvik vs JVM</h2><ul><li><strong>JVM (Java Virtual Machine)</strong>: 基于<strong>栈</strong>架构。指令通常较短，但执行一个操作需要更多的指令。</li><li><strong>Dalvik VM</strong>: 基于<strong>寄存器</strong>架构。指令更长且更复杂，但通常执行速度更快，且针对移动设备内存有限的情况进行了优化。</li><li><strong>文件格式</strong>: JVM 运行 <code>.class</code> 文件；Dalvik 运行 <code>.dex</code> (Dalvik Executable) 文件（由多个类合并而成，减少冗余）。</li></ul><h2 id="_2-art-android-runtime" tabindex="-1"><a class="header-anchor" href="#_2-art-android-runtime" aria-hidden="true">#</a> 2. ART (Android Runtime)</h2><p>从 Android 5.0 开始，ART 取代了 Dalvik。</p><ul><li><strong>Dalvik</strong>: 使用 JIT (Just-In-Time) 编译，应用运行时将字节码翻译为机器码。</li><li><strong>ART</strong>: 使用 AOT (Ahead-Of-Time) 编译，在安装时预编译。这提高了运行速度但增加了安装时间和存储空间。</li></ul><h2 id="_3-smali-指令基础" tabindex="-1"><a class="header-anchor" href="#_3-smali-指令基础" aria-hidden="true">#</a> 3. Smali 指令基础</h2><p>Smali 是 <code>.dex</code> 文件的汇编语言表现形式。</p><h3 id="寄存器命名" tabindex="-1"><a class="header-anchor" href="#寄存器命名" aria-hidden="true">#</a> 寄存器命名</h3><ul><li><strong>v 命名法</strong>: <code>v0</code>, <code>v1</code>, ... 代表局部寄存器。</li><li><strong>p 命名法</strong>: <code>p0</code>, <code>p1</code>, ... 代表参数寄存器。 <ul><li>对于非静态方法，<code>p0</code> 总是 <code>this</code> 指针。</li><li><code>p1</code> 是第一个参数，以此类推。</li></ul></li></ul><h3 id="基础语法" tabindex="-1"><a class="header-anchor" href="#基础语法" aria-hidden="true">#</a> 基础语法</h3><ul><li><code>.method</code>: 方法声明。</li><li><code>.end method</code>: 方法结束。</li><li><code>.field</code>: 字段声明。</li><li><code>.parameter</code>: 参数声明。</li><li><code>.registers</code>: 声明该方法使用的寄存器总数。</li></ul><h3 id="常用指令" tabindex="-1"><a class="header-anchor" href="#常用指令" aria-hidden="true">#</a> 常用指令</h3><ul><li><strong>数据操作</strong>: <ul><li><code>const/4 v0, 0x1</code>: 将常量 1 放入 v0。</li><li><code>move v0, v1</code>: 将 v1 的值赋给 v0。</li></ul></li><li><strong>对象/字段操作</strong>: <ul><li><code>new-instance v0, Ljava/lang/StringBuilder;</code>: 创建对象实例。</li><li><code>iget-object v0, p0, Lcom/app/MainActivity;-&gt;name:Ljava/lang/String;</code>: 获取成员变量。</li><li><code>iput-object v1, p0, Lcom/app/MainActivity;-&gt;name:Ljava/lang/String;</code>: 设置成员变量。</li></ul></li><li><strong>方法调用</strong>: <ul><li><code>invoke-virtual {p0, v0}, Lcom/app/MainActivity;-&gt;check(Ljava/lang/String;)Z</code>: 调用虚拟方法。</li><li><code>invoke-static {v0}, Landroid/text/TextUtils;-&gt;isEmpty(Ljava/lang/CharSequence;)Z</code>: 调用静态方法。</li></ul></li><li><strong>判断与跳转</strong>: <ul><li><code>if-eq v0, v1, :cond_0</code>: 如果 v0 == v1，跳转到 cond_0。</li><li><code>goto :goto_0</code>: 无条件跳转。</li></ul></li></ul><h2 id="_4-类型描述符" tabindex="-1"><a class="header-anchor" href="#_4-类型描述符" aria-hidden="true">#</a> 4. 类型描述符</h2><table><thead><tr><th style="text-align:left;">标识符</th><th style="text-align:left;">Java 类型</th></tr></thead><tbody><tr><td style="text-align:left;">V</td><td style="text-align:left;">void</td></tr><tr><td style="text-align:left;">Z</td><td style="text-align:left;">boolean</td></tr><tr><td style="text-align:left;">B</td><td style="text-align:left;">byte</td></tr><tr><td style="text-align:left;">C</td><td style="text-align:left;">char</td></tr><tr><td style="text-align:left;">S</td><td style="text-align:left;">short</td></tr><tr><td style="text-align:left;">I</td><td style="text-align:left;">int</td></tr><tr><td style="text-align:left;">J</td><td style="text-align:left;">long</td></tr><tr><td style="text-align:left;">F</td><td style="text-align:left;">float</td></tr><tr><td style="text-align:left;">D</td><td style="text-align:left;">double</td></tr><tr><td style="text-align:left;">Lpackage/name;</td><td style="text-align:left;">对象类型 (如 Ljava/lang/String;)</td></tr><tr><td style="text-align:left;">[</td><td style="text-align:left;">数组 (如 [I 代表 int[])</td></tr></tbody></table>',17),o=[d];function n(r,c){return e(),l("div",null,o)}const h=t(a,[["render",n],["__file","dalvik.html.vue"]]);export{h as default};
